'use strict';
// Private one-shot PDFium worker. Input/output are created by the host in its
// private job directory; no shell, remote fetch, user paths or model text.
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib');
global.fetch=async()=>{throw Error('PDF渲染网络访问已禁用');};
const {PDFiumLibrary}=require('./index.cjs');
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function chunk(type,data){const b=Buffer.alloc(12+data.length);b.writeUInt32BE(data.length);b.write(type,4,4,'ascii');data.copy(b,8);b.writeUInt32BE(crc32(b.subarray(4,8+data.length)),8+data.length);return b;}
function png(width,height,data){if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width>1600||height>1600||width*height>2560000||data.byteLength!==width*height*4)throw Error('PDF页面尺寸超限');const header=Buffer.alloc(13);header.writeUInt32BE(width);header.writeUInt32BE(height,4);header[8]=8;header[9]=6;const rows=Buffer.alloc((width*4+1)*height);for(let y=0;y<height;y++)Buffer.from(data.buffer,data.byteOffset+y*width*4,width*4).copy(rows,y*(width*4+1)+1);return Buffer.concat([Buffer.from('89504e470d0a1a0a','hex'),chunk('IHDR',header),chunk('IDAT',zlib.deflateSync(rows,{level:6})),chunk('IEND',Buffer.alloc(0))]);}
(async()=>{const [mode,input,pageArg,output]=process.argv.slice(2);if(!['info','render'].includes(mode)||!path.isAbsolute(input)||path.dirname(input)!==process.cwd()||path.basename(input)!=='source.pdf')throw Error('PDF渲染输入无效');if(mode==='render'&&(!/^\d{1,3}$/.test(pageArg||'')||!path.isAbsolute(output||'')||path.dirname(output)!==process.cwd()||path.basename(output)!=='page.png'))throw Error('PDF页面参数无效');const stat=fs.lstatSync(input);if(!stat.isFile()||stat.isSymbolicLink()||stat.size<5||stat.size>16*1024*1024)throw Error('PDF文件无效或超限');const fd=fs.openSync(input,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let bytes;try{bytes=fs.readFileSync(fd);}finally{fs.closeSync(fd);}if(bytes.length!==stat.size||bytes.subarray(0,5).toString()!=='%PDF-')throw Error('PDF文件已变化');const wasm=fs.readFileSync(path.join(__dirname,'pdfium.wasm'));const lib=await PDFiumLibrary.init({wasmBinary:wasm});let doc;try{doc=await lib.loadDocument(bytes);const pages=doc.getPageCount();if(!Number.isInteger(pages)||pages<1||pages>100)throw Error('PDF页数超限');if(mode==='info'){process.stdout.write(JSON.stringify({pages}));return;}const pageNum=Number(pageArg);if(pageNum<1||pageNum>pages)throw Error('PDF页码无效');const page=doc.getPage(pageNum-1);try{const {originalWidth:w,originalHeight:h}=page.getOriginalSize();if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0||w>200000||h>200000)throw Error('PDF页面尺寸无效');const scale=1600/Math.max(w,h);const result=await page.render({scale,renderFormFields:false,transparent:false,render:async({data,width,height})=>png(width,height,data)});if(result.data.length>4*1024*1024)throw Error('PDF页面图片超过4MiB');fs.writeFileSync(output,result.data,{flag:'wx',mode:0o600});process.stdout.write(JSON.stringify({page:pageNum,width:result.width,height:result.height}));}finally{page.close();}}finally{doc?.destroy();lib.destroy();}})().catch(e=>{process.stderr.write(String(e?.message||e).slice(0,500));process.exitCode=1;});
